import { afterAll, describe, expect, it, vi } from "vitest";
import fs from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { resolveImages } from "../../src/lib/image-input.js";
import {
  inspectImageHeader,
  MAX_INPUT_IMAGE_BYTES,
} from "../../src/lib/image-file-boundary.js";
import {
  PNG_BYTES,
  imageHeader,
  imageFsFixture,
} from "../helpers/image-file-fixtures.js";

const root = fs.mkdtempSync(join(tmpdir(), "cc-image-boundary-"));
afterAll(() => fs.rmSync(root, { recursive: true, force: true }));
function file(name, data = PNG_BYTES, size) {
  const target = join(root, name);
  fs.writeFileSync(target, data);
  if (size) fs.truncateSync(target, size);
  return target;
}

describe("CLI final image input boundary", () => {
  it.each(["png", "jpeg", "gif", "webp"])(
    "recognizes bounded %s headers",
    (format) => {
      expect(inspectImageHeader(imageHeader(format))).toMatchObject({
        mediaType: `image/${format}`,
      });
      expect(
        resolveImages([file(`valid.${format}`, imageHeader(format))])[0]
          .mediaType,
      ).toBe(`image/${format}`);
    },
  );

  it("rejects a forged extension and malformed header before returning content", () => {
    expect(() => resolveImages([file("mismatch.jpg")])).toThrow(
      /extension does not match/,
    );
    expect(() =>
      resolveImages([file("invalid.png", Buffer.from("not an image"))]),
    ).toThrow(/malformed image header/);
    expect(() => resolveImages([file("empty.png", Buffer.alloc(0))])).toThrow(
      /1 byte to 20 MiB/,
    );
  });

  it("rejects zero and oversized pixel declarations", () => {
    for (const width of [0, 40_000_001]) {
      const bytes = Buffer.from(PNG_BYTES);
      bytes.writeUInt32BE(width, 16);
      expect(() => resolveImages([file(`pixel-${width}.png`, bytes)])).toThrow(
        /40 megapixels/,
      );
    }
  });

  it("bounds file size before any read or full-buffer allocation", () => {
    const target = file("oversized.png", PNG_BYTES, MAX_INPUT_IMAGE_BYTES + 1);
    const readSync = vi.fn(fs.readSync);
    const closeSync = vi.fn(fs.closeSync);
    expect(() =>
      resolveImages([target], { fs: { ...fs, readSync, closeSync } }),
    ).toThrow(/20 MiB/);
    expect(readSync).not.toHaveBeenCalled();
    expect(closeSync).toHaveBeenCalledOnce();
  });

  it("bounds the combined attachment bytes and identifies the failing entry", () => {
    const a = file("total-a.png", PNG_BYTES, 11 * 1024 * 1024);
    const b = file("total-b.png", PNG_BYTES, 11 * 1024 * 1024);
    expect(() => resolveImages([a, b])).toThrow(
      /Image 2: Total image attachments exceed 20 MiB/,
    );
  });

  it("rejects excess image count before opening files", () => {
    const openSync = vi.fn();
    expect(() =>
      resolveImages(Array(9).fill("same.png"), { fs: { openSync } }),
    ).toThrow(/at most 8/);
    expect(openSync).not.toHaveBeenCalled();
  });

  it("rejects non-regular handles and closes them", () => {
    const io = imageFsFixture();
    io.fstatSync = () => ({ isFile: () => false });
    io.closeSync = vi.fn();
    io.readSync = vi.fn();
    expect(() => resolveImages(["pipe.png"], { fs: io })).toThrow(
      /regular file/,
    );
    expect(io.readSync).not.toHaveBeenCalled();
    expect(io.closeSync).toHaveBeenCalledOnce();
  });

  it("uses bounded descriptor reads when the file grows after its size check", () => {
    const target = file("growing.png");
    let changed = false;
    const readSync = vi.fn((...args) => {
      const read = fs.readSync(...args);
      if (!changed) {
        changed = true;
        fs.appendFileSync(target, Buffer.alloc(1024));
      }
      return read;
    });
    const closeSync = vi.fn(fs.closeSync);
    expect(() =>
      resolveImages([target], { fs: { ...fs, readSync, closeSync } }),
    ).toThrow(/changed while being read/);
    expect(
      readSync.mock.calls.every((args) => args[3] <= PNG_BYTES.length + 1),
    ).toBe(true);
    expect(closeSync).toHaveBeenCalledOnce();
  });

  it.each(["mtimeMs", "ctimeMs"])(
    "rejects a same-size image whose pinned handle %s changes",
    (field) => {
      const io = imageFsFixture();
      let stats = 0;
      const baseStat = io.fstatSync;
      io.fstatSync = vi.fn((fd) => ({
        ...baseStat(fd),
        [field]: ++stats === 1 ? 1 : 2,
      }));
      io.closeSync = vi.fn();
      // The bytes, header, size and handle remain identical. Only the metadata
      // transition distinguishes this raced input from the valid control.
      expect(() => resolveImages(["stable.png"], { fs: io })).toThrow(
        /changed while being read/,
      );
      expect(io.fstatSync).toHaveBeenCalledTimes(2);
      expect(io.closeSync).toHaveBeenCalledOnce();
      const valid = imageFsFixture();
      expect(resolveImages(["stable.png"], { fs: valid })[0].data).toBe(
        PNG_BYTES.toString("base64"),
      );
    },
  );

  it("supports short reads and rejects a truncated file", () => {
    const target = file("short-read.png");
    const readSync = (fd, data, offset, length, position) =>
      fs.readSync(fd, data, offset, Math.min(length, 7), position);
    expect(resolveImages([target], { fs: { ...fs, readSync } })[0].data).toBe(
      PNG_BYTES.toString("base64"),
    );
    let reads = 0;
    const truncated = (...args) => (++reads === 1 ? fs.readSync(...args) : 0);
    expect(() =>
      resolveImages([target], { fs: { ...fs, readSync: truncated } }),
    ).toThrow(/changed while being read/);
  });

  it("caps JPEG header scanning at 1 MiB", () => {
    const segment = Buffer.alloc(65537);
    segment[0] = 255;
    segment[1] = 224;
    segment.writeUInt16BE(65535, 2);
    const data = Buffer.concat([
      Buffer.from([255, 216]),
      ...Array(17).fill(segment),
      imageHeader("jpeg").subarray(2),
    ]);
    expect(() => resolveImages([file("late-dimensions.jpg", data)])).toThrow(
      /first 1 MiB/,
    );
  });
});

import { afterEach, describe, expect, it, vi } from "vitest";
import fs from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
// From __tests__, ../src resolves to packages/cli/src (not ../../src).
import { readBoundedImage } from "../src/lib/image-file-boundary.js";

const BYTE_LIMIT = 20 * 1024 * 1024;
const roots = [];
// A complete 1x1 PNG; this boundary admits headers, not decoded pixels.
const PNG = Buffer.from(
  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aX1sAAAAASUVORK5CYII=",
  "base64",
);

afterEach(() => {
  for (const root of roots.splice(0)) {
    fs.rmSync(root, { recursive: true, force: true });
  }
});

function image(bytes = PNG, size = bytes.length) {
  const root = fs.mkdtempSync(join(tmpdir(), "same-handle-image-"));
  roots.push(root);
  const path = join(root, "input.png");
  fs.writeFileSync(path, bytes);
  if (size !== bytes.length) fs.truncateSync(path, size);
  return path;
}

function trackedIo(overrides = {}) {
  return {
    openSync: vi.fn(overrides.openSync || ((...args) => fs.openSync(...args))),
    fstatSync: vi.fn(overrides.fstatSync || ((...args) => fs.fstatSync(...args))),
    readSync: vi.fn(overrides.readSync || ((...args) => fs.readSync(...args))),
    closeSync: vi.fn((...args) => fs.closeSync(...args)),
  };
}

function closedOnSameHandle(io, path) {
  expect(io.openSync).toHaveBeenCalledTimes(1);
  expect(io.openSync.mock.calls[0][0]).toBe(path);
  const fd = io.openSync.mock.results[0].value;
  expect(Number.isInteger(fd)).toBe(true);
  expect(io.closeSync.mock.calls).toEqual([[fd]]);
  for (const [usedFd] of [...io.fstatSync.mock.calls, ...io.readSync.mock.calls]) {
    expect(usedFd).toBe(fd);
  }
  // Verify real closure, not merely that a spy was called.
  expect(() => fs.fstatSync(fd)).toThrow(expect.objectContaining({ code: "EBADF" }));
}

function read(path, io, remaining = BYTE_LIMIT, mediaType = "image/png") {
  return readBoundedImage(path, mediaType, remaining, io);
}

describe("independent same-handle image boundary regressions", () => {
  it("reads a small PNG through short descriptor reads and closes the real handle", () => {
    const path = image();
    const io = trackedIo({
      readSync: (fd, data, offset, length, position) =>
        fs.readSync(fd, data, offset, Math.min(length, 7), position),
    });
    try {
      const data = read(path, io);
      expect(Buffer.isBuffer(data)).toBe(true);
      expect(data.length).toBe(PNG.length);
      expect(data.equals(PNG)).toBe(true);
      expect(io.fstatSync).toHaveBeenCalledTimes(2);
      expect(io.readSync.mock.calls.length).toBeGreaterThan(2);
    } finally {
      closedOnSameHandle(io, path);
    }
  });

  it("pins the original inode even if its pathname is replaced before the first read", () => {
    for (const replace of [false, true]) {
      const path = image();
      const replacement = Buffer.from(PNG);
      replacement.writeUInt32BE(2, 16);
      const io = trackedIo({
        openSync: (...args) => {
          const fd = fs.openSync(...args);
          if (replace) {
            fs.renameSync(path, `${path}.original`);
            fs.writeFileSync(path, replacement);
          }
          return fd;
        },
      });
      try {
        const data = read(path, io);
        expect(data.length).toBe(PNG.length);
        expect(data.equals(PNG)).toBe(true);
        if (replace) {
          expect(fs.readFileSync(path).equals(replacement)).toBe(true);
          expect(data.equals(replacement)).toBe(false);
        }
      } finally {
        closedOnSameHandle(io, path);
      }
    }
  });

  it("accepts exactly 20 MiB and rejects the first excess byte before reading", () => {
    for (const size of [BYTE_LIMIT, BYTE_LIMIT + 1]) {
      const path = image(PNG, size); // Sparse padding avoids a large input allocation.
      const io = trackedIo();
      try {
        if (size === BYTE_LIMIT) {
          const data = read(path, io);
          expect(data.length).toBe(BYTE_LIMIT);
          const expected = Buffer.alloc(BYTE_LIMIT);
          PNG.copy(expected);
          expect(data.equals(expected)).toBe(true);
          expect(io.fstatSync).toHaveBeenCalledTimes(2);
        } else {
          expect(() => read(path, io)).toThrow("Image must contain 1 byte to 20 MiB");
          expect(io.readSync).not.toHaveBeenCalled();
          expect(io.fstatSync).toHaveBeenCalledTimes(1);
        }
      } finally {
        closedOnSameHandle(io, path);
      }
    }
  });

  it.each([
    [40_000_000, 1, 40_000_001, 1],
    [1, 1, 0, 1],
    [1, 1, 1, 0],
  ])("isolates pixel admission: %i x %i versus %i x %i", (w, h, badW, badH) => {
    for (const [width, height, accepted] of [[w, h, true], [badW, badH, false]]) {
      const bytes = Buffer.from(PNG);
      bytes.writeUInt32BE(width, 16);
      bytes.writeUInt32BE(height, 20);
      const path = image(bytes);
      const io = trackedIo();
      try {
        if (accepted) {
          expect(read(path, io).equals(bytes)).toBe(true);
        } else {
          expect(() => read(path, io)).toThrow(
            "Image dimensions must be positive and at most 40 megapixels",
          );
          expect(io.fstatSync).toHaveBeenCalledTimes(1);
          expect(io.readSync).toHaveBeenCalledTimes(1); // Header only.
        }
      } finally {
        closedOnSameHandle(io, path);
      }
    }
